                   #ece0cb; /* same derivation as --label (literal reuse) (token:text.body) */\n  --label--disabled:                    #ab9578; /* muted text colour (token:text.muted) */\n  --neutral-100:                        #fff8ea; /* heading ink (lightest/most emphatic text colour) (token:text.heading) */\n  --icon:                               #ece0cb; /* reuses body text colour -- neither pack declares a distinct icon ink (token:text.body) */\n  --icon--hover:                        #c08a4a; /* accent colour on hover (token:accent.primary) */\n  --icon--selected:                     #c08a4a; /* same as --icon--hover (literal reuse; no distinct selected-icon token) (ref:--icon--hover) */\n  --icon--disabled:                     rgba(171,149,120,0.6); /* muted text colour at reduced alpha (ref:--label--disabled) */\n  --callToAction:                       #c08a4a; /* primary accent colour (token:accent.primary) */\n  --callToAction--hover:                #cb9f6b; /* the pack\'s own buttons/primary:hover colour when it declares a solid one, else its secondary accent, else --callToAction itself (variant:buttons/primary:hover:backgroundColor) */\n  --callToAction--active:               #a3753f; /* --callToAction darkened 15% -- neither pack declares a distinct :active state (ref:--callToAction) */\n  --callToAction--disabled:             rgba(192,138,74,0.35); /* --callToAction at reduced alpha (ref:--callToAction) */\n  --callToActionHighlight:              #291d15; /* the pack\'s own active-nav wash, flattened over the page (token:surface.nav-active) */\n  --error:                              #e08a7a; /* danger accent -- first candidate legible as ink on a card (token:accent.danger) */\n  --warning:                            #d29922; /* medium-priority alarm colour (token:accent.alarm-med) */\n  --success:                            #8cc08e; /* positive-delta accent (falls back to the OK status text colour) (token:accent.delta-up) */\n  --info:             